def resolves(loc):
    p = loc[len('https://utilityexplained.com'):]
    p = p.lstrip('/')
    d = os.path.join(public, p)
    if os.path.isdir(d): return ('dir', p)
    for f in ['index.html','sitemap.xml','robots.txt']:
        if os.path.isfile(os.path.join(d,f)): return ('file:'+f, p)
    # page with index.html inside
    if os.path.isfile(os.path.join(d,'index.html')): return ('index.html', p)
    return (None, p)
